/// <summary>
/// This method maps the entity fields to data source fields, added custom logic to handle ValidFrom field mapping
/// </summary>
/// <param name = "_entityCtx">DataEntityRuntimeContext</param>
/// <param name = "_dataSourceCtx">DataEntityDataSourceRuntimeContext</param>
public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    if (_entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Insert 
        && _dataSourceCtx.name() == dataEntityDataSourceStr(PurchProductApprovedVendorEntity, PdsApprovedVendorList))
    {
        PdsApprovedVendorList pdsApprovedVendorList = _dataSourceCtx.getBuffer();
        if (this.EffectiveDate == dateNull())
        {
            pdsApprovedVendorList.ValidFrom = dateNull();
        }
    }

    next mapEntityToDataSource(_entityCtx, _dataSourceCtx);
}
